}

.nav-button {
    -fx-background-color: transparent;
    -fx-background-radius: 9px;
    -fx-border-width: 0;
    -fx-cursor: hand;
    -fx-alignment: CENTER_LEFT;
    -fx-padding: 11px 13px;
    -fx-text-fill: #b2bfbd;
    -fx-font-size: 13px;
}

.nav-button:hover,
.nav-button-active {
    -fx-background-color: #334143;
    -fx-text-fill: #f7f8ee;
}

.nav-button-active {
    -fx-font-weight: bold;
}

.sidebar-footer .separator {
    -fx-border-color: #3b4849;
}

.sidebar-tip {
    -fx-text-fill: #aeb9b7;
    -fx-font-size: 12px;
    -fx-line-spacing: 3px;
}
